def _reference_balance(protocol: CampaignProtocol) -> np.ndarray:
    """Conserved quantity every sample must match.

    The balance of a reaction network is the quantity preserved by its
    stoichiometry.  A protocol whose record names the conserved totals
    explicitly uses those; the default is the composition at the start of
    the integration, the total concentration the public protocols conserve.
    """
    record = getattr(protocol, "balance_reference", None)
    if record is None:
        return np.asarray(protocol.model.initial_composition, dtype=float)
    reference = np.asarray(record, dtype=float)
    if reference.shape != np.asarray(
        protocol.model.initial_composition, dtype=float
    ).shape:
        raise ValueError("balance reference must match the composition shape")
    return reference

