def _reference_balance(protocol: CampaignProtocol) -> float:
    """Conserved total the composition must preserve at every sample.

    The mass balance of a reaction network is the quantity preserved by its
    stoichiometry.  A protocol whose record names the conserved total
    explicitly uses that; the default is the total concentration present at
    the start of the integration, the quantity the public protocols conserve.
    """
    record = getattr(protocol, "balance_reference", None)
    if record is None:
        return float(np.sum(np.asarray(protocol.model.initial_composition)))
    return float(record)

